import { sqliteTable, text, integer } from 'drizzle-orm/sqlite-core';

export const persone = sqliteTable('persone', {
  id: text('id').primaryKey(),
  nome: text('nome').notNull(),
  cognome: text('cognome').notNull(),
  codiceFiscale: text('codice_fiscale').unique(),
  email: text('email'),
  telefono: text('telefono'),
  dataNascita: text('data_nascita'), // ISO8601
  luogoNascita: text('luogo_nascita'),
  paeseNascita: text('paese_nascita'),
  genere: text('genere'),
  professione: text('professione'),
  matricola: text('matricola'),
  note: text('note'),
  createdAt: text('created_at').notNull(), // ISO8601
  updatedAt: text('updated_at').notNull(),
});

export const periodiVolontario = sqliteTable('periodi_volontario', {
  id: text('id').primaryKey(),
  personaId: text('persona_id').notNull().references(() => persone.id),
  status: text('status').notNull(), // 'attivo' | 'inattivo' | 'sospeso' | 'dimesso'
  dataIscrizione: text('data_iscrizione').notNull(),
  dataUscita: text('data_uscita'),
  motivoUscita: text('motivo_uscita'),
  note: text('note'),
  createdAt: text('created_at').notNull(),
});

export const periodiSocio = sqliteTable('periodi_socio', {
  id: text('id').primaryKey(),
  personaId: text('persona_id').notNull().references(() => persone.id),
  periodoVolontarioId: text('periodo_volontario_id').notNull().references(() => periodiVolontario.id),
  dataAmmissione: text('data_ammissione').notNull(),
  dataDimissione: text('data_dimissione'),
  motivoUscita: text('motivo_uscita'),
  riferimentoArt: text('riferimento_art'),
  assembleaAmmissioneId: text('assemblea_ammissione_id').references(() => assemblee.id),
  assembleaUscitaId: text('assemblea_uscita_id').references(() => assemblee.id),
  note: text('note'),
  createdAt: text('created_at').notNull(),
});

export const assemblee = sqliteTable('assemblee', {
  id: text('id').primaryKey(),
  tipo: text('tipo').notNull(), // 'ordinaria' | 'straordinaria' | 'consiglio_direttivo'
  numero: integer('numero').notNull(),
  dataConvocazione: text('data_convocazione').notNull(),
  dataPrimaConv: text('data_prima_conv').notNull(),
  oraPrimaConv: text('ora_prima_conv').notNull(),
  dataSecondaConv: text('data_seconda_conv'),
  oraSecondaConv: text('ora_seconda_conv'),
  sede: text('sede').notNull(),
  modalita: text('modalita').notNull(), // 'presenza' | 'telematica' | 'mista'
  assembleaTenuta: text('assemblea_tenuta'), // 'prima' | 'seconda' | 'nessuna'
  presidente: text('presidente').notNull(),
  segretario: text('segretario').notNull(),
  note: text('note'),
  createdAt: text('created_at').notNull(),
  updatedAt: text('updated_at').notNull(),
});

export const ordiniDelGiorno = sqliteTable('ordini_del_giorno', {
  id: text('id').primaryKey(),
  assembleaId: text('assemblea_id').notNull().references(() => assemblee.id),
  numero: integer('numero').notNull(),
  titolo: text('titolo').notNull(),
  descrizione: text('descrizione'),
  delibera: text('delibera'),
  createdAt: text('created_at').notNull(),
});

export const presenze = sqliteTable('presenze', {
  id: text('id').primaryKey(),
  assembleaId: text('assemblea_id').notNull().references(() => assemblee.id),
  personaId: text('persona_id').notNull().references(() => persone.id),
  modalita: text('modalita').notNull(), // 'presenza' | 'telematica' | 'delega'
  deleganteId: text('delegante_id').references(() => persone.id),
  createdAt: text('created_at').notNull(),
});
