import { Hono } from 'hono';
import { drizzle } from 'drizzle-orm/d1';
import { eq } from 'drizzle-orm';
import { persone } from '../db/schema';
import { createSelectSchema, createInsertSchema } from 'drizzle-zod';
import { z } from 'zod';

type Bindings = {
  DB: D1Database;
};

const personeRouter = new Hono<{ Bindings: Bindings }>();

// Zod schemas for validation
const insertPersonaSchema = createInsertSchema(persone);
const patchPersonaSchema = insertPersonaSchema.partial();

// GET /api/persone - List all people
personeRouter.get('/', async (c) => {
  const db = drizzle(c.env.DB);
  const result = await db.select().from(persone).all();
  return c.json(result);
});

// GET /api/persone/:id - Get person by ID
personeRouter.get('/:id', async (c) => {
  const id = c.req.param('id');
  const db = drizzle(c.env.DB);
  const result = await db.select().from(persone).where(eq(persone.id, id)).get();
  
  if (!result) {
    return c.json({ error: 'Persona non trovata' }, 404);
  }
  
  return c.json(result);
});

// POST /api/persone - Create a new person
personeRouter.post('/', async (c) => {
  const body = await c.req.json();
  const db = drizzle(c.env.DB);
  
  const validation = insertPersonaSchema.safeParse({
    ...body,
    id: body.id || crypto.randomUUID(),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });
  
  if (!validation.success) {
    return c.json({ error: 'Dati non validi', details: validation.error.format() }, 400);
  }
  
  const result = await db.insert(persone).values(validation.data).returning().get();
  return c.json(result, 201);
});

// PATCH /api/persone/:id - Update person details
personeRouter.patch('/:id', async (c) => {
  const id = c.req.param('id');
  const body = await c.req.json();
  const db = drizzle(c.env.DB);
  
  const validation = patchPersonaSchema.safeParse({
    ...body,
    updatedAt: new Date().toISOString(),
  });
  
  if (!validation.success) {
    return c.json({ error: 'Dati non validi', details: validation.error.format() }, 400);
  }
  
  const result = await db.update(persone)
    .set(validation.data)
    .where(eq(persone.id, id))
    .returning()
    .get();
    
  if (!result) {
    return c.json({ error: 'Persona non trovata' }, 404);
  }
  
  return c.json(result);
});

export { personeRouter };
